6	import type { Context, MiddlewareHandler } from '../..'
7	import type { AddressType, GetConnInfo } from '../../helper/conninfo'
8	import { HTTPException } from '../../http-exception'
9	import type { InvalidIPAddressError } from '../../utils/ipaddr'
10	import {
11	  convertIPv4MappedIPv6ToIPv4,
12	  convertIPv4ToBinary,
13	  convertIPv6BinaryToString,
14	  convertIPv6ToBinary,
15	  distinctRemoteAddr,
16	  isIPv4MappedIPv6,
17	  INVALID_IP_ADDRESS_ERROR_CODE,
18	} from '../../utils/ipaddr'
19	
20	/**
21	 * Function to get IP Address
22	 */
23	type GetIPAddr = GetConnInfo | ((c: Context) => string)
24	
25	/**
26	 * ### IPv4 and IPv6
27	 * - `*` match all
28	 *
29	 * ### IPv4
30	 * - `192.168.2.0` static
31	 * - `192.168.2.0/24` CIDR Notation
32	 *
33	 * ### IPv6
34	 * - `::1` static
35	 * - `::1/10` CIDR Notation
36	 */
37	type IPRestrictionRuleFunction = (addr: { addr: string; type: AddressType }) => boolean
38	export type IPRestrictionRule = string | ((addr: { addr: string; type: AddressType }) => boolean)
39	
40	const IS_CIDR_NOTATION_REGEX = /\/[^/]*$/
41	const parseCidrPrefix = (rule: string, prefix: string, max: number): number => {
42	  if (!/^[0-9]{1,3}$/.test(prefix)) {
43	    throw new TypeError(`Invalid rule: ${rule}`)
44	  }
45	  const parsedPrefix = parseInt(prefix)
46	  if (parsedPrefix > max) {
47	    throw new TypeError(`Invalid rule: ${rule}`)
48	  }
49	  return parsedPrefix
50	}
51	const buildMatcher = (
52	  rules: IPRestrictionRule[]
53	): ((addr: { addr: string; type: AddressType; isIPv4: boolean }) => boolean) => {
54	  const functionRules: IPRestrictionRuleFunction[] = []
55	  const staticRules: Set<string> = new Set()
56	  const staticIPv4Rules: Set<bigint> = new Set()
57	  const staticIPv6Rules: Set<bigint> = new Set()
58	  const cidrRules: [boolean, bigint, bigint][] = []
59	  const registerStaticRule = (rule: string): void => {
60	    const type = distinctRemoteAddr(rule)
61	    if (type === undefined) {
62	      throw new TypeError(`Invalid rule: ${rule}`)
63	    }
64	    if (type === 'IPv4') {
65	      const ipv4binary = convertIPv4ToBinary(rule)
66	      staticRules.add(rule)
67	      staticRules.add(`::ffff:${rule}`)
68	      staticIPv4Rules.add(ipv4binary)
69	      staticIPv6Rules.add((0xffffn << 32n) | ipv4binary)
70	    } else {
71	      const ipv6binary = convertIPv6ToBinary(rule)
72	      const ipv6Addr = convertIPv6BinaryToString(ipv6binary)
73	      staticRules.add(ipv6Addr)
74	      staticIPv6Rules.add(ipv6binary)
75	      if (isIPv4MappedIPv6(ipv6binary)) {
76	        staticRules.add(ipv6Addr.substring(7)) // remove ::ffff: prefix
77	        staticIPv4Rules.add(convertIPv4MappedIPv6ToIPv4(ipv6binary))
78	      }
79	    }
80	  }
81	
82	  for (let rule of rules) {
83	    if (rule === '*') {
84	      return () => true
85	    } else if (typeof rule === 'function') {
86	      functionRules.push(rule)
87	    } else {
88	      if (IS_CIDR_NOTATION_REGEX.test(rule)) {
89	        const separatedRule = rule.split('/')
90	
91	        const addrStr = separatedRule[0]
92	        const type = distinctRemoteAddr(addrStr)
93	        if (type === undefined) {
94	          throw new TypeError(`Invalid rule: ${rule}`)
95	        }
96	
97	        let isIPv4 = type === 'IPv4'
98	        let prefix = parseCidrPrefix(rule, separatedRule[1], isIPv4 ? 32 : 128)
99	
100	        if (isIPv4 ? prefix === 32 : prefix === 128) {
101	          // this rule is a static rule
102	          rule = addrStr
103	        } else {
104	          let addr = (isIPv4 ? convertIPv4ToBinary : convertIPv6ToBinary)(addrStr)
105	          if (type === 'IPv6' && isIPv4MappedIPv6(addr) && prefix >= 96) {
106	            isIPv4 = true
107	            addr = convertIPv4MappedIPv6ToIPv4(addr)
108	            prefix -= 96
109	          }
110	
111	          const mask = ((1n << BigInt(prefix)) - 1n) << BigInt((isIPv4 ? 32 : 128) - prefix)
112	
113	          cidrRules.push([isIPv4, addr & mask, mask] as [boolean, bigint, bigint])
114	          continue
115	        }
116	      }
117	
118	      registerStaticRule(rule)
119	    }
120	  }
121	
122	  return (remote: {
123	    addr: string
124	    type: AddressType
125	    isIPv4: boolean
126	    binaryAddr?: bigint
127	  }): boolean => {
128	    if (staticRules.has(remote.addr)) {
129	      return true
130	    }
131	    const remoteAddr = (remote.binaryAddr ||= (
132	      remote.isIPv4 ? convertIPv4ToBinary : convertIPv6ToBinary
133	    )(remote.addr))
134	    const remoteIPv4Addr =
135	      remote.isIPv4 || isIPv4MappedIPv6(remoteAddr)
136	        ? remote.isIPv4
137	          ? remoteAddr
138	          : convertIPv4MappedIPv6ToIPv4(remoteAddr)
139	        : undefined
140	    if ((remote.isIPv4 ? staticIPv4Rules : staticIPv6Rules).has(remoteAddr)) {
141	      return true
142	    }
143	    for (const [isIPv4, addr, mask] of cidrRules) {
144	      if (isIPv4) {
145	        if (remoteIPv4Addr === undefined) {
146	          continue
147	        }
148	        if ((remoteIPv4Addr & mask) === addr) {
149	          return true
150	        }
151	        continue
152	      }
153	      if (remote.isIPv4) {
154	        continue
155	      }
156	      if ((remoteAddr & mask) === addr) {
157	        return true
158	      }
159	    }
160	    for (const rule of functionRules) {
161	      if (rule({ addr: remote.addr, type: remote.type })) {
162	        return true
163	      }
164	    }
165	    return false
166	  }
167	}
