177	/**
178	 * IP Restriction Middleware for Hono.
179	 *
180	 * @see {@link https://hono.dev/docs/middleware/builtin/ip-restriction}
181	 *
182	 * @param {GetConnInfo | ((c: Context) => string)} getIP - A function to retrieve the client IP address. Use `getConnInfo` from the appropriate runtime adapter.
183	 * @param {IPRestrictionRules} rules - An object with optional `denyList` and `allowList` arrays of IP rules. Each rule can be a static IP, a CIDR range, or a custom function.
184	 * @param {(remote: { addr: string; type: AddressType }, c: Context) => Response | Promise<Response>} [onError] - Optional custom handler invoked when a request is blocked. Defaults to returning a 403 Forbidden response.
185	 * @returns {MiddlewareHandler} The middleware handler function.
186	 *
187	 * @example
188	 * ```ts
189	 * import { Hono } from 'hono'
190	 * import { ipRestriction } from 'hono/ip-restriction'
191	 * import { getConnInfo } from 'hono/cloudflare-workers'
192	 *
193	 * const app = new Hono()
194	 *
195	 * app.use(
196	 *   '*',
197	 *   ipRestriction(getConnInfo, {
198	 *     // Block a specific IP and an entire subnet
199	 *     denyList: ['192.168.0.5', '10.0.0.0/8'],
200	 *     // Only allow requests from localhost and a private range
201	 *     allowList: ['127.0.0.1', '::1', '192.168.1.0/24'],
202	 *   })
203	 * )
204	 *
205	 * // With a custom error handler
206	 * app.use(
207	 *   '/admin/*',
208	 *   ipRestriction(
209	 *     getConnInfo,
210	 *     { allowList: ['203.0.113.0/24'] },
211	 *     (remote, c) => c.text(`Access denied for ${remote.addr}`, 403)
212	 *   )
213	 * )
214	 *
215	 * app.get('/', (c) => c.text('Hello!'))
216	 * ```
217	 */
218	export const ipRestriction = (
219	  getIP: GetIPAddr,
220	  { denyList = [], allowList = [] }: IPRestrictionRules,
221	  onError?: (
222	    remote: { addr: string; type: AddressType },
223	    c: Context
224	  ) => Response | Promise<Response>
225	): MiddlewareHandler => {
226	  const allowLength = allowList.length
227	
228	  const denyMatcher = buildMatcher(denyList)
229	  const allowMatcher = buildMatcher(allowList)
230	
231	  const blockError = (c: Context): HTTPException =>
232	    new HTTPException(403, {
233	      res: c.text('Forbidden', {
234	        status: 403,
235	      }),
236	    })
237	
238	  return async function ipRestriction(c, next) {
