/**
 * @module
 * Rate Limit Middleware for Hono.
 */

import type { Context } from '../../context'
import type { Env, MiddlewareHandler } from '../../types'

interface RateLimitRecord {
  count: number
  resetAt: number
}

interface RateLimitOptions {
  limit?: number
  windowMs?: number
  keyGenerator?: (c: Context) => string
  skip?: (c: Context) => boolean
  handler?: (c: Context) => Response | Promise<Response>
}

const defaultKeyGenerator = (c: Context): string => {
  const forwardedFor = c.req.header('x-forwarded-for')
  if (forwardedFor) {
    return forwardedFor.split(',')[0].trim()
  }
  return c.req.header('x-real-ip') ?? 'unknown'
}

const defaultHandler = (): Response =>
  new Response(JSON.stringify({ error: 'Too Many Requests' }), {
    status: 429,
    headers: { 'content-type': 'application/json' },
  })

/**
 * Rate Limit Middleware for Hono.
 *
 * Limits the number of requests a client can make within a fixed time window.
 * When the limit is exceeded, a 429 Too Many Requests response is returned.
 *
 * @param {RateLimitOptions} [options] - The options for the rate limit middleware.
 * @param {number} [options.limit=100] - The maximum number of requests allowed per window.
 * @param {number} [options.windowMs=60000] - The time window in milliseconds.
 * @param {(c: Context) => string} [options.keyGenerator] - A function returning the key used to identify a client. Defaults to the remote IP from `x-forwarded-for` or `x-real-ip` headers.
 * @param {(c: Context) => boolean} [options.skip] - A function that can be used to skip rate limiting for certain requests.
 * @param {(c: Context) => Response | Promise<Response>} [options.handler] - A custom handler invoked when the limit is exceeded. Defaults to a JSON 429 response.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use('/api/*', rateLimit({ limit: 10, windowMs: 60_000 }))
 *
 * app.get('/api/hello', (c) => c.text('hello'))
 * ```
 */
export const rateLimit = <E extends Env = Env>(
  options?: RateLimitOptions
): MiddlewareHandler<E> => {
  const limit = options?.limit ?? 100
  const windowMs = options?.windowMs ?? 60000
  const keyGenerator = options?.keyGenerator ?? defaultKeyGenerator
  const skip = options?.skip
  const handler = options?.handler ?? defaultHandler

  const store = new Map<string, RateLimitRecord>()

  return async function rateLimit(c, next) {
    if (skip?.(c)) {
      return next()
    }

    const key = keyGenerator(c)
    const now = Date.now()

    let record = store.get(key)
    if (!record || record.resetAt <= now) {
      record = { count: 0, resetAt: now + windowMs }
      store.set(key, record)
    }

    record.count++

    if (record.count > limit) {
      return handler(c)
    }

    await next()
  }
}

export type { RateLimitOptions }

