import type { Context } from '../../context'
import { Hono } from '../../hono'
import { rateLimit } from '.'

describe('Rate Limit Middleware', () => {
  describe('default options', () => {
    let app: Hono

    beforeEach(() => {
      app = new Hono()
      app.use('*', rateLimit({ limit: 3, windowMs: 60_000 }))
      app.get('/', (c) => c.text('hello'))
    })

    it('Should allow requests under the limit', async () => {
      for (let i = 0; i < 3; i++) {
        const res = await app.request('/', {
          headers: { 'x-forwarded-for': '1.2.3.4' },
        })
        expect(res.status).toBe(200)
        expect(await res.text()).toBe('hello')
      }
    })

    it('Should return 429 once the limit is exceeded', async () => {
      for (let i = 0; i < 3; i++) {
        await app.request('/', { headers: { 'x-forwarded-for': '1.2.3.4' } })
      }
      const res = await app.request('/', {
        headers: { 'x-forwarded-for': '1.2.3.4' },
      })
      expect(res.status).toBe(429)
      expect(res.headers.get('content-type')).toMatch(/application\/json/)
      const body = (await res.json()) as { error: string }
      expect(body.error).toBe('Too Many Requests')
    })

    it('Should track limits per key', async () => {
      for (let i = 0; i < 3; i++) {
        const res = await app.request('/', {
          headers: { 'x-forwarded-for': '1.1.1.1' },
        })
        expect(res.status).toBe(200)
      }
      const blocked = await app.request('/', {
        headers: { 'x-forwarded-for': '1.1.1.1' },
      })
      expect(blocked.status).toBe(429)

      const otherClient = await app.request('/', {
        headers: { 'x-forwarded-for': '2.2.2.2' },
      })
      expect(otherClient.status).toBe(200)
    })

    it('Should fall back to a default key when no IP headers are present', async () => {
      for (let i = 0; i < 3; i++) {
        const res = await app.request('/')
        expect(res.status).toBe(200)
      }
      const res = await app.request('/')
      expect(res.status).toBe(429)
    })
  })

  describe('windowMs', () => {
    it('Should reset the counter once the window has elapsed', async () => {
      vi.useFakeTimers()
      try {
        const app = new Hono()
        app.use('*', rateLimit({ limit: 2, windowMs: 1000 }))
        app.get('/', (c) => c.text('hello'))

        for (let i = 0; i < 2; i++) {
          const res = await app.request('/', {
            headers: { 'x-forwarded-for': '9.9.9.9' },
          })
          expect(res.status).toBe(200)
        }
        const blocked = await app.request('/', {
          headers: { 'x-forwarded-for': '9.9.9.9' },
        })
        expect(blocked.status).toBe(429)

        vi.advanceTimersByTime(1001)

        const afterReset = await app.request('/', {
          headers: { 'x-forwarded-for': '9.9.9.9' },
        })
        expect(afterReset.status).toBe(200)
      } finally {
        vi.useRealTimers()
      }
    })
  })

  describe('keyGenerator', () => {
    it('Should use the custom key generator', async () => {
      const app = new Hono()
      app.use(
        '*',
        rateLimit({
          limit: 1,
          windowMs: 60_000,
          keyGenerator: (c: Context) => c.req.header('x-user-id') ?? 'anonymous',
        })
      )
      app.get('/', (c) => c.text('hello'))

      const first = await app.request('/', {
        headers: { 'x-user-id': 'alice' },
      })
      expect(first.status).toBe(200)

      const second = await app.request('/', {
        headers: { 'x-user-id': 'alice' },
      })
      expect(second.status).toBe(429)

      const otherUser = await app.request('/', {
        headers: { 'x-user-id': 'bob' },
      })
      expect(otherUser.status).toBe(200)
    })
  })

  describe('skip', () => {
    it('Should skip rate limiting when skip returns true', async () => {
      const app = new Hono()
      app.use(
        '*',
        rateLimit({
          limit: 1,
          windowMs: 60_000,
          skip: (c: Context) => c.req.path.startsWith('/health'),
        })
      )
      app.get('/health', (c) => c.text('ok'))
      app.get('/api', (c) => c.text('api'))

      for (let i = 0; i < 5; i++) {
        const res = await app.request('/health', {
          headers: { 'x-forwarded-for': '8.8.8.8' },
        })
        expect(res.status).toBe(200)
      }

      const allowed = await app.request('/api', {
        headers: { 'x-forwarded-for': '8.8.8.8' },
      })
      expect(allowed.status).toBe(200)
      const blocked = await app.request('/api', {
        headers: { 'x-forwarded-for': '8.8.8.8' },
      })
      expect(blocked.status).toBe(429)
    })
  })

  describe('handler', () => {
    it('Should use the custom handler when the limit is exceeded', async () => {
      const app = new Hono()
      app.use(
        '*',
        rateLimit({
          limit: 1,
          windowMs: 60_000,
          handler: (c: Context) => c.text('slow down', 429),
        })
      )
      app.get('/', (c) => c.text('hello'))

      const first = await app.request('/', {
        headers: { 'x-forwarded-for': '7.7.7.7' },
      })
      expect(first.status).toBe(200)

      const second = await app.request('/', {
        headers: { 'x-forwarded-for': '7.7.7.7' },
      })
      expect(second.status).toBe(429)
      expect(await second.text()).toBe('slow down')
    })
  })

  describe('keyGenerator using x-forwarded-for list', () => {
    it('Should use the first IP from a comma-separated list', async () => {
      const app = new Hono()
      app.use('*', rateLimit({ limit: 1, windowMs: 60_000 }))
      app.get('/', (c) => c.text('hello'))

      const first = await app.request('/', {
        headers: { 'x-forwarded-for': '5.5.5.5, 10.0.0.1' },
      })
      expect(first.status).toBe(200)

      const blocked = await app.request('/', {
        headers: { 'x-forwarded-for': '5.5.5.5, 10.0.0.2' },
      })
      expect(blocked.status).toBe(429)
    })
  })
})

