      const first = await app.request('/', {
        headers: { 'x-forwarded-for': '7.7.7.7' },
      })
      expect(first.status).toBe(200)

      const second = await app.request('/', {
        headers: { 'x-forwarded-for': '7.7.7.7' },
      })
      expect(second.status).toBe(429)
      expect(await second.text()).toBe('slow down')
    })
  })

  describe('keyGenerator using x-forwarded-for list', () => {
    it('Should use the first IP from a comma-separated list', async () => {
      const app = new Hono()
      app.use('*', rateLimit({ limit: 1, windowMs: 60_000 }))
      app.get('/', (c) => c.text('hello'))

      const first = await app.request('/', {
        headers: { 'x-forwarded-for': '5.5.5.5, 10.0.0.1' },
      })
      expect(first.status).toBe(200)

      const blocked = await app.request('/', {
        headers: { 'x-forwarded-for': '5.5.5.5, 10.0.0.2' },
      })
      expect(blocked.status).toBe(429)
    })
  })
